import type { Board } from './board';

/**
 * Board plus aggregate counts, as listed on the `/` dashboard (`_docs/specs.md` §10).
 */
export type BoardSummary = Board & {
  /** @minimum 0 */
  readonly columnCount: number;
  /**
     * Total tasks across all of the board's columns.
     * @minimum 0
     */
  readonly taskCount: number;
};
